package com.tehang.enterpriserisk.service;
import java.io.*;import java.util.*;import org.apache.poi.ss.usermodel.*;import org.apache.poi.xssf.usermodel.XSSFWorkbook;import org.springframework.stereotype.Service;import org.springframework.web.multipart.MultipartFile;
@Service public class EnterpriseImportService {
 private final RiskService risk; public EnterpriseImportService(RiskService r){risk=r;}
 public byte[] template(){try(var wb=new XSSFWorkbook();var out=new ByteArrayOutputStream()){var s=wb.createSheet("企业导入");var h=s.createRow(0);String[] hs={"企业名称","统一社会信用代码","销售经理","主体类型"};for(int i=0;i<hs.length;i++){h.createCell(i).setCellValue(hs[i]);s.setColumnWidth(i,24*256);}wb.write(out);return out.toByteArray();}catch(IOException e){throw new IllegalStateException(e);}}
 public Map<String,Object> importXlsx(MultipartFile file,boolean reactivateDeleted){if(file==null||file.isEmpty()||file.getOriginalFilename()==null||!file.getOriginalFilename().toLowerCase(Locale.ROOT).endsWith(".xlsx"))throw new IllegalArgumentException("请上传 .xlsx 文件");List<Map<String,Object>> errors=new ArrayList<>();List<String[]> valid=new ArrayList<>();int total=0,success=0;Set<String> seen=new HashSet<>();try(var wb=new XSSFWorkbook(file.getInputStream())){Sheet s=wb.getSheetAt(0);Row header=s.getRow(0);if(header==null||!"企业名称".equals(text(header.getCell(0)))||!"统一社会信用代码".equals(text(header.getCell(1)))||!"销售经理".equals(text(header.getCell(2)))||!"主体类型".equals(text(header.getCell(3))))throw new IllegalArgumentException("模板列必须为：企业名称、统一社会信用代码、销售经理、主体类型");for(int i=1;i<=s.getLastRowNum();i++){Row row=s.getRow(i);if(row==null||blank(row))continue;total++;String name=text(row.getCell(0)),code=text(row.getCell(1)).toUpperCase(Locale.ROOT),sales=text(row.getCell(2)),type=text(row.getCell(3));if(type.isBlank())type="ENTERPRISE";String problem=name.isBlank()?"企业名称不能为空":code.length()!=18?"统一社会信用代码必须为18位":sales.isBlank()?"销售经理不能为空":!Set.of("ENTERPRISE","GOVERNMENT","OTHER").contains(type)?"主体类型无效":!seen.add(code)?"文件内统一社会信用代码重复":null;if(problem!=null)errors.add(Map.of("row",i+1,"message",problem));else valid.add(new String[]{name,code,sales,type});}}catch(IOException e){throw new IllegalArgumentException("Excel 读取失败："+e.getMessage());}long deletedCount=valid.stream().filter(row->risk.isDeletedCode(row[1])).count();if(deletedCount>0&&!reactivateDeleted)return Map.of("requiresReactivationConfirmation",true,"historicalDeletedCount",deletedCount,"total",total,"failed",errors.size(),"errors",errors);for(String[] row:valid)try{risk.upsert(row[1],row[0],row[3],true,"RISK_IMPORT",row[2],true);success++;}catch(Exception e){errors.add(Map.of("message",e.getMessage()==null?"保存失败":e.getMessage()));}return Map.of("total",total,"success",success,"failed",errors.size(),"errors",errors);}
 private String text(Cell c){return c==null?"":new DataFormatter().formatCellValue(c).trim();}private boolean blank(Row r){return text(r.getCell(0)).isBlank()&&text(r.getCell(1)).isBlank()&&text(r.getCell(2)).isBlank()&&text(r.getCell(3)).isBlank();}
}
